package dev.exodus.network;
import dev.exodus.map.*;import net.minecraft.network.FriendlyByteBuf;import java.util.*;
public final class MatchMapPacket {private MatchMapPacket(){}
 public static void encode(MatchMapSnapshot p,FriendlyByteBuf b){b.writeLong(p.epoch());b.writeLong(p.revision());b.writeBoolean(p.matchId()!=null);if(p.matchId()!=null)b.writeUUID(p.matchId());b.writeUtf(p.dimension(),160);b.writeInt(p.centerX());b.writeInt(p.centerZ());b.writeInt(p.borderSize());b.writeBoolean(p.clear());b.writeVarInt(p.locations().size());for(MapLocation l:p.locations()){b.writeUtf(l.id(),160);b.writeUtf(l.label(),160);b.writeEnum(l.kind());b.writeInt(l.x());b.writeInt(l.y());b.writeInt(l.z());}b.writeVarInt(p.teammates().size());for(UUID id:p.teammates())b.writeUUID(id);}
 public static MatchMapSnapshot decode(FriendlyByteBuf b){long epoch=b.readLong(),revision=b.readLong();UUID match=b.readBoolean()?b.readUUID():null;String dimension=b.readUtf(160);int x=b.readInt(),z=b.readInt(),size=b.readInt();boolean clear=b.readBoolean();int count=b.readVarInt();if(count<0||count>MatchMapSnapshot.MAX_LOCATIONS)throw new IllegalArgumentException("Too many map locations");List<MapLocation> locations=new ArrayList<>();for(int i=0;i<count;i++)locations.add(new MapLocation(b.readUtf(160),b.readUtf(160),b.readEnum(MapLocation.Kind.class),b.readInt(),b.readInt(),b.readInt()));int teammateCount=b.readVarInt();if(teammateCount<0||teammateCount>1)throw new IllegalArgumentException("Too many teammates");Set<UUID> teammates=new HashSet<>();for(int i=0;i<teammateCount;i++)teammates.add(b.readUUID());return new MatchMapSnapshot(epoch,revision,match,dimension,x,z,size,clear,locations,teammates);}
}
